import torch,torch.nn as nn; exec("class Solution:\n    def detect_dead_neurons(self, model, x):\n        dead_fractions = []\n        with torch.no_grad():\n            h = x\n            for layer in model:\n                h = layer(h)\n                if isinstance(layer, nn.ReLU):\n                    dead = (h == 0).all(dim=0).float()\n                    dead_fractions.append(round(float(dead.mean()), 4))\n        return dead_fractions\n    def suggest_fix(self, dead_fractions):\n        if any(d > 0.5 for d in dead_fractions):\n            return 'use_leaky_relu'\n        if dead_fractions and dead_fractions[0] > 0.3:\n            return 'reinitialize'\n        strictly_increasing = all(dead_fractions[i] < dead_fractions[i+1] for i in range(len(dead_fractions)-1))\n        if strictly_increasing and dead_fractions and dead_fractions[-1] > 0.1:\n            return 'reduce_learning_rate'\n        if dead_fractions and max(dead_fractions) < 0.1:\n            return 'healthy'\n        return 'healthy'")